    "category": "Acute stroke care",
    "q": "Which drugs and fixed BP target does the PDF give for hemorrhagic stroke?",
    "a": "No tPA; rapidly lower BP with labetalol, nicardipine or hydralazine to systolic below 140 mm Hg. This is its blanket source target, not a target for every hemorrhage severity or initial pressure.",
